import os

# Let's check what files are available in the current directory
print("Current directory:", os.getcwd())
print("\nFiles in current directory:")
print(os.listdir('.'))

# Let's look for SQLite database files
print("\nLooking for SQLite database files...")
for file in os.listdir('.'):
    if file.endswith('.db') or file.endswith('.sqlite') or file.endswith('.sqlite3'):
        print(f"Found database file: {file}")
        db_path = file
        break
else:
    # If no database found, let's check one level up
    parent_dir = os.path.dirname(os.getcwd())
    print(f"\nChecking parent directory: {parent_dir}")
    if os.path.exists(parent_dir):
        for file in os.listdir(parent_dir):
            if file.endswith('.db') or file.endswith('.sqlite') or file.endswith('.sqlite3'):
                print(f"Found database file: {file}")
                db_path = os.path.join(parent_dir, file)
                break
        else:
            print("No SQLite database files found in current or parent directory")
            db_path = None
    else:
        db_path = None

if db_path:
    print(f"\nUsing database path: {db_path}")
else:
    print("\nPlease specify the correct database path")
